const edition = globalThis.makeSubjectEdition({"year":2022,"grade":"8-11","tasksFile":"zr_2122_zadanija_lq_8-11.pdf","answersFile":"reviewed-8-11.pdf","title":"Герои Отечества","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":45,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2022/8-11.json","sections":[{"start":1,"title":"Государственные деятели и монархи"},{"start":16,"title":"Преобразователи и первопроходчики"},{"start":31,"title":"Благотворители и просветители"}],"reviewedKey":true}, [{"title":"Исторический князь на сцене","question":"Этот исторический деятель стал героем пьес и А. С. Пушкина, и А. К. Толстого, и А. П. Сумарокова.","choices":["Иван Грозный","Князь Шуйский","Борис Годунов","Фёдор Годунов"],"answer":1,"steps":["В пушкинском «Борисе Годунове» этот боярин расследует обстоятельства гибели царевича и участвует в придворной борьбе.","Василий Шуйский также действует в драматических произведениях Алексея Толстого и Сумарокова."]},{"title":"Символ на открытке Билибина","question":"На открытке И. Я. Билибина, выдержанной в иконописном стиле, изображены главные символы правления Ярослава Мудрого, включая первый русский …","choices":["исторический свод","свод законов","указ о книгохранилище","церковный устав"],"answer":1,"steps":["Один из важнейших памятников древнерусского права связан с Ярославом Мудрым и его наследниками.","Это «Русская Правда», ранний письменный свод законов."],"figure":{"src":"assets/golden-fleece/2022/lessons/8-11/2.webp","alt":"Мужчина в княжеской одежде держит книгу","width":144,"height":232}},{"title":"Монашеское имя","question":"Это имя принял в монашестве Фёдор Никитич — отец основателя царской династии Романовых.","choices":["Феодосий","Филарет","Сергий","Серафим"],"answer":1,"steps":["Фёдор Никитич Романов был отцом царя Михаила Фёдоровича.","После пострига он получил имя Филарет, а позднее стал патриархом."]},{"title":"Срок рекрутской службы","question":"В результате военной реформы Петра I солдаты стали служить…","choices":["пожизненно","по найму","только во время войны","25 лет"],"answer":0,"steps":["При Петре I действовала рекрутская повинность, а единый срок в 25 лет установили уже позднее, в XVIII веке.","Первоначально солдаты-рекруты служили пожизненно, пока были годны к службе."]},{"title":"География и летописи","question":"Этот учёный в ходе порученной ему Петром I работы по географическому описанию России начал собирать исторические материалы, на основе которых был создан первый капитальный труд по русской истории.","choices":["Н. М. Карамзин","В. Н. Татищев","В. О. Ключевский","С. М. Соловьёв"],"answer":1,"steps":["Собирая материалы для географического описания России, исследователь обращался к летописям и старинным письменным памятникам.","Получился многотомный труд Василия Никитича Татищева «История Российская»."]},{"title":"Когда отлили статую","question":"По чьему указу отлили конную статую Петра I по модели Бартоломео Карло Растрелли, которая сегодня стоит перед Михайловским замком?","choices":["Елизаветы Петровны","Екатерины I","Екатерины II","Павла I"],"answer":0,"steps":["Бартоломео Карло Растрелли создал модель памятника. Отливку из бронзы выполнили уже после смерти скульптора, в царствование Елизаветы Петровны по её распоряжению.","У Михайловского замка памятник установили в 1800 году по распоряжению Павла I."],"references":["https://app.rusmuseum.ru/mikhailovsky-castle/history/","https://www.prlib.ru/item/681538","https://old.bigenc.ru/fine_art/text/3495090","https://petersmonuments.ru/russia/memorials/pamyatnik-petru-i-u-mikhaylovskogo-inzhenernogo-zamka-s-peterburg/"],"taskUrl":"https://runodog.ru/ZR_2122/zr_2122_zadanija_lq_8-11.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам.","figure":{"src":"assets/golden-fleece/2022/lessons/3-4/25.webp","alt":"Конная скульптура на площади","width":198,"height":158}},{"title":"Надзор за чиновниками","question":"Эта должность была введена Петром I для борьбы с казнокрадством и коррупцией.","choices":["Камергер","Президент коллегии","Канцлер","Фискал"],"answer":3,"steps":["Пётр I ввёл должность тайного надзора за злоупотреблениями и нарушениями государственных интересов.","Чиновник, сообщавший о таких нарушениях, назывался фискалом."]},{"title":"Новый пост в министерстве","question":"Этот государственный деятель был первым министром народного просвещения в России.","choices":["А. С. Шишков","П. В. Завадовский","А. Н. Голицын","А. К. Разумовский"],"answer":1,"steps":["Министерство народного просвещения образовали при Александре I в 1802 году.","Его первым руководителем стал Пётр Васильевич Завадовский."]},{"title":"Реформатор в романе","question":"Этот российский реформатор стал одним из персонажей романа Л. Н. Толстого «Война и мир».","choices":["С. П. Румянцев","С. Ю. Витте","И. И. Бецкой","М. М. Сперанский"],"answer":3,"steps":["В «Войне и мире» князь Андрей знакомится с государственным деятелем, которого поначалу воспринимает как образец разума и деловитости.","Толстой так изображает Михаила Михайловича Сперанского."]},{"title":"Слова рассказчика у Пушкина","question":"Главный герой повести А. С. Пушкина «Капитанская дочка» был благодарен Александру I за…","choices":["основание лицея","внедрение военных поселений","отмену пыток","взятие Парижа"],"answer":2,"steps":["Гринёв рассказывает о жестоком обращении с башкирцем и сравнивает своё время с более поздней эпохой.","В этом отступлении он благодарит Александра I за отмену пыток."]},{"title":"Систематизация законов","question":"Под руководством этого государственного деятеля был сформирован и опубликован свод законов Российской империи.","choices":["Г. А. Потёмкин","М. М. Сперанский","В. Н. Татищев","И. И. Бецкой"],"answer":1,"steps":["Во Втором отделении императорской канцелярии подготовили Полное собрание законов, а затем Свод действующих законов.","Работой по их систематизации руководил Михаил Сперанский."],"figure":{"src":"assets/golden-fleece/2022/lessons/8-11/11.webp","alt":"Мужчина в сюртуке с книгой на коленях","width":157,"height":201}},{"title":"Подсчёт населения страны","question":"По инициативе П. П. Семёнова-Тян-Шанского в 1897 году была организована…","choices":["крестьянская реформа","всероссийская перепись населения","научная экспедиция в Африку","промышленная выставка"],"answer":1,"steps":["Пётр Семёнов-Тян-Шанский много лет работал в статистических учреждениях и выступал за единообразный учёт населения.","В 1897 году состоялась первая всеобщая перепись населения Российской империи."]},{"title":"Призыв на площади","question":"Главный герой картины К. Е. Маковского призывает народ к пожертвованиям на создание…","choices":["ополчения","храма","кремля","моста"],"answer":0,"steps":["Константин Маковский изобразил Кузьму Минина, обращающегося к жителям Нижнего Новгорода.","Деньги собирают на народное ополчение, позднее освободившее Москву в 1612 году."],"figure":{"src":"assets/golden-fleece/2022/lessons/8-11/13.webp","alt":"Картина с собравшейся на площади толпой","width":476,"height":560,"detailSrc":"assets/golden-fleece/2022/lessons/8-11/13-detail.webp"}},{"title":"Женщины и лекции","question":"В правление какого императора в Петербургском университете в 1859 году появились женщины-вольнослушательницы?","choices":["Александра I","Николая I","Александра II","Николая II"],"answer":2,"steps":["В 1859 году женщины получили возможность посещать публичные лекции в Петербургском университете.","Это произошло в правление Александра II. Всеобщий доступ к университетскому образованию для женщин установился позднее."],"references":["https://sev.msu.ru/pdf/prich/prich-b-2012.pdf"]},{"title":"Река на банкноте","question":"На одной из банкнот Банка России изображён памятник генерал-губернатору Восточной Сибири, установленный на набережной реки…","choices":["Амур","Енисей","Обь","Лена"],"answer":0,"steps":["На банкноте с видами Хабаровска изображён памятник Николаю Муравьёву-Амурскому.","Город и его знаменитая набережная стоят на Амуре."],"figure":{"src":"assets/golden-fleece/2022/lessons/8-11/15.webp","alt":"Скульптура на высоком постаменте у реки","width":156,"height":194}},{"title":"Путь тверского купца","question":"Этот путешественник совершил экспедицию «за три моря», одно из которых он называл «Индейским».","choices":["С. И. Дежнёв","Н. Н. Миклухо-Маклай","Н. М. Пржевальский","А. Никитин"],"answer":3,"steps":["Автор «Хожения за три моря» отправился из Твери и несколько лет провёл в Индии.","Путевые записи принадлежат Афанасию Никитину."]},{"title":"История о сне учёного","question":"Этот учёный отрицал миф о том, что самое великое своё открытие он сделал во сне.","choices":["Н. И. Лобачевский","Д. И. Менделеев","А. Г. Столетов","М. В. Ломоносов"],"answer":1,"steps":["Легенда утверждает, будто таблица элементов приснилась учёному уже в готовом виде.","Дмитрий Менделеев в действительности много лет систематически изучал свойства элементов и искал закономерности."]},{"title":"История и самопознание","question":"Кто из русских историков рассматривал историю как науку народного самопознания и написал «Историю России с древнейших времён»?","choices":["Н. М. Карамзин","В. О. Ключевский","С. М. Соловьёв","С. Ф. Платонов"],"answer":2,"steps":["Автор многотомной «Истории России с древнейших времён» рассматривал изучение прошлого как способ народа понять себя.","Это российский историк Сергей Михайлович Соловьёв."]},{"title":"Герой рок-оперы","question":"Этот путешественник стал прообразом главного героя рок-оперы «Юнона и Авось».","choices":["Н. П. Резанов","И. Ф. Крузенштерн","Ю. Ф. Лисянский","Ф. Ф. Беллинсгаузен"],"answer":0,"steps":["В рок-опере показаны плавание к берегам Калифорнии и встреча русского путешественника с Кончитой Аргуэльо.","Историческим прообразом героя был Николай Петрович Резанов."]},{"title":"Географ и комиссии","question":"Этот выдающийся путешественник участвовал в работе Редакционных комиссий по подготовке крестьянской реформы 1861 года.","choices":["Г. И. Невельской","П. П. Семёнов-Тян-Шанский","Н. М. Пржевальский","Н. П. Резанов"],"answer":1,"steps":["Этот исследователь не только совершил путешествия в Тянь-Шань, но и участвовал в государственной и статистической работе.","В подготовке крестьянской реформы работал Пётр Петрович Семёнов, впоследствии Семёнов-Тян-Шанский."]},{"title":"Название части побережья","question":"Как называлась в русской географической традиции часть северо-восточного побережья Новой Гвинеи, где работал Н. Н. Миклухо-Маклай?","choices":["Земля Санникова","Берег Маклая","Атолл Моту-Оне","Остров Папаапохо"],"answer":1,"steps":["Николай Миклухо-Маклай изучал жизнь населения северо-восточного побережья Новой Гвинеи возле залива Астролябия.","В русской географической традиции этот участок известен как Берег Маклая."],"adaptation":"В вопросе используется историческое название побережья."},{"title":"Прибавление к фамилии","question":"Этот путешественник получил географическую приставку к фамилии в качестве почётного титула.","choices":["СИ. Челюскин","П. П. Семёнов","С. И. Дежнёв","Н. М. Пржевальский"],"answer":1,"steps":["Путешествия Петра Петровича Семёнова сделали известными его исследования Тянь-Шаня.","В память об этих работах к фамилии Семёнов разрешили прибавить «Тян-Шанский»."]},{"title":"Инженер нефтепровода","question":"Первый российский нефтепровод был построен по проекту и под техническим руководством …","choices":["Д. И. Менделеева","А. С. Попова","В. К. Зворыкина","В. Г. Шухова"],"answer":3,"steps":["В конце 1870-х годов в районе Баку построили нефтепровод от промыслов к переработке.","Проект и техническое руководство связаны с инженером Владимиром Григорьевичем Шуховым."]},{"title":"Электрический свет на улице","question":"Кто изобрёл электрические «свечи» с двумя параллельными угольными стержнями, которыми освещали улицы Парижа?","choices":["В. В. Петров","П. Н. Яблочков","А. С. Попов","А. Н. Лодыгин"],"answer":1,"steps":["У такой свечи светит электрическая дуга между двумя угольными стержнями. Во второй половине XIX века такие светильники появились на улицах Парижа.","Электрическую свечу сконструировал Павел Николаевич Яблочков. Лодыгин работал с лампами накаливания, где светит нагретый проводник."],"adaptation":"Уточнён вид источника света. Лампы Лодыгина также использовались для уличного освещения.","references":["https://www.prlib.ru/node/2060401","https://www.prlib.ru/Great_Russia/outstanding_scientists_XX/Lodygin"]},{"title":"Иная геометрия","question":"Этого русского учёного, создавшего одну из неевклидовых геометрий, называли «Коперником геометрии».","choices":["И. М. Виноградов","А. Н. Колмогоров","Н. И. Лобачевский","А. Н. Крылов"],"answer":2,"steps":["Математик разработал геометрию, в которой через точку вне прямой проходит более одной прямой, не пересекающей данную.","За смену привычной картины пространства Николая Ивановича Лобачевского сравнивали с Коперником."]},{"title":"Первый объект на орбите","question":"Выдающийся советский учёный, конструктор С. П. Королёв руководил проектом по созданию и запуску первого в мире…","choices":["подводного самолёта","атомного ледокола","искусственного спутника Земли","ударного вертолёта"],"answer":2,"steps":["В октябре 1957 года с Земли запустили небольшой металлический аппарат, передававший радиосигналы.","Первым искусственным спутником Земли стал ПС-1, созданный коллективом под руководством Сергея Королёва."]},{"title":"Лётчик у Кассиля","question":"Этот лётчик стал прообразом Климентия Черемыша, героя книги Л. А. Кассиля.","choices":["М. М. Громов","В. П. Чкалов","А. В. Беляков","Г. Ф. Байдуков"],"answer":1,"steps":["В книге «Черемыш — брат героя» мальчик выдаёт себя за родственника прославленного лётчика.","Образ Климентия Черемыша напоминает знаменитого пилота дальних перелётов Валерия Чкалова."]},{"title":"Позывной в небе","question":"Малая планета (1671) Chaika («Чайка») была названа в честь…","choices":["А. А. Ахматовой","М. М. Плисецкой","В. В. Терешковой","С. В. Ковалевской"],"answer":2,"steps":["Астероид (1671) Chaika назвали по радиопозывному первой женщины-космонавта.","Позывной «Чайка» в полёте на «Востоке-6» использовала Валентина Терешкова."]},{"title":"Наука и сан","question":"За исследования в какой области архиепископ Лука (В. Ф. Войно-Ясенецкий) был удостоен Сталинской премии?","choices":["химии","археологии","медицины","физики"],"answer":2,"steps":["Архиепископ Лука, в миру Валентин Войно-Ясенецкий, был практикующим хирургом и автором трудов о лечении гнойных заболеваний.","Его научную работу отметили премией за вклад в медицину."]},{"title":"Ледокол и полярная экспедиция","question":"Этот ледокол был награждён орденом Трудового Красного Знамени за спасение итальянских полярных исследователей и немецкого пассажирского судна.","choices":["Ермак","Юрий Лисянский","Красин","Семён Дежнёв"],"answer":2,"steps":["В 1928 году советский ледокол отправился на помощь участникам итальянской экспедиции Умберто Нобиле.","В этой и последующих спасательных операциях прославился ледокол «Красин»."]},{"title":"Житие от первого лица","question":"Лидер и идеолог старообрядчества считается создателем первой в истории русской литературы …","choices":["летописи","автобиографии","азбуки","поэмы"],"answer":1,"steps":["Протопоп Аввакум сам рассказал о своей жизни, испытаниях и ссылках в «Житии протопопа Аввакума, им самим написанном».","Такой рассказ автора о собственной жизни — автобиография."]},{"title":"Строки Державина","question":"Этому просветителю Г. Р. Державин посвятил строки: «Кто для себя — ты жил для всех».","choices":["И. И. Шувалов","Н. И. Новиков","А. К. Нартов","И. И. Бецкой"],"answer":3,"steps":["Строки обращены к деятелю, занимавшемуся созданием воспитательных домов и образовательных учреждений при Екатерине II.","В стихотворении «На кончину благотворителя» Державин вспоминал Ивана Ивановича Бецкого."]},{"title":"Первое слово словаря","question":"История создания «Толкового словаря живого великорусского языка» В. И. Даля началась со слова…","choices":["Ведренеть","Замораживать","Замолаживать","Ведреть"],"answer":2,"steps":["В молодости Даль услышал от ямщика слово о перемене погоды и записал его значение.","Этим первым известным словарным наблюдением было «замолаживать» — пасмурнеть, заволакиваться тучами."]},{"title":"Долгое президентство","question":"Кто занимал пост президента Петербургской академии наук с 1746 по 1798 год?","choices":["И. И. Шувалов","К. Г. Разумовский","Л. Л. Блюментрост","С. С. Уваров"],"answer":1,"steps":["Кирилла Разумовского назначили президентом Петербургской академии наук в 1746 году.","Формально он занимал этот пост более полувека, до последних лет жизни."],"adaptation":"В вопросе указаны годы официального пребывания в должности.","figure":{"src":"assets/golden-fleece/2022/lessons/8-11/34.webp","alt":"Мужчина в красном кафтане на портрете","width":144,"height":187}},{"title":"Школа зодчих","question":"Первую архитектурную школу в России основал…","choices":["Д. В. Ухтомский","А. В. Квасов","В. П. Стасов","А. Ф. Кокоринов"],"answer":0,"steps":["Князь-архитектор руководил строительными работами в Москве и организовал профессиональное обучение будущих зодчих.","Школа, где учились архитекторы XVIII века, связана с именем Дмитрия Васильевича Ухтомского."]},{"title":"Религиозная лирика в живописи","question":"Самые известные картины этого художника отличаются религиозно-лирической направленностью.","choices":["И. Е. Репин","М. В. Нестеров","В. М. Васнецов","А. Н. Бенуа"],"answer":1,"steps":["Пример такой живописи — «Видение отроку Варфоломею», где духовное событие разворачивается среди тихой русской природы.","Картину написал Михаил Васильевич Нестеров."]},{"title":"Коллекция новой живописи","question":"Приобретение в конце XIX века этим меценатом полотен художников-импрессионистов стало основой всемирно известной коллекции.","choices":["П. М. Третьяков","А. А. Бахрушин","Н. П. Рябушинский","С. И. Щукин"],"answer":3,"steps":["Московский коллекционер приобрёл произведения Моне, Гогена, Матисса и Пикассо, когда эта живопись ещё вызывала споры.","Собрание одного из самых известных таких меценатов принадлежало Сергею Ивановичу Щукину."]},{"title":"Память о тюремном враче","question":"На ограде надгробного памятника этому врачу помещены кандалы в знак его усилий по облегчению участи заключённых и ссыльных.","choices":["И. П. Павлов","Н. И. Пирогов","Ф. П. Гааз","Н. В. Склифосовский"],"answer":2,"steps":["Московский врач добивался облегчения условий пересылки заключённых и улучшения медицинской помощи.","Кандалы на ограде могилы напоминают о работе Фёдора Петровича Гааза."]},{"title":"Театральный музей","question":"Этот купец и меценат в 1913 году передал в ведение Санкт-Петербургской академии наук созданный им Музей театрального искусства.","choices":["С. И. Мамонтов","А. А. Бахрушин","М. А. Морозов","С. И. Щукин"],"answer":1,"steps":["Предприниматель собирал афиши, костюмы и театральные реликвии и создал музей в Москве.","В 1913 году Алексей Александрович Бахрушин передал своё собрание в ведение Императорской академии наук."]},{"title":"Петербургская святая","question":"Эта святая считается небесной покровительницей Санкт-Петербурга.","choices":["Варвара","Ксения","Ольга","Екатерина"],"answer":1,"steps":["Почитание этой блаженной связано со Смоленским кладбищем, где стоит посвящённая ей часовня.","Среди святых покровителей города называют Ксению Петербургскую."],"figure":{"src":"assets/golden-fleece/2022/lessons/8-11/40.webp","alt":"Икона женщины в платке","width":140,"height":192}},{"title":"Откуда взяты слова","question":"В стихотворении «Победителям», посвящённом защитникам Ленинграда во время Великой Отечественной войны, Анна Ахматова цитирует слова из …","choices":["русской былины","«Науки побеждать» А. В. Суворова","Евангелия","«Искусства войны» Сунь-Цзы"],"answer":2,"steps":["Ахматова пишет о тех, кто отдаёт «душу свою за други своя».","Это отсылка к Евангелию от Иоанна о любви человека, который полагает душу за друзей своих."]},{"title":"Церковь на кладбище","question":"В строительстве этой церкви помогала блаженная Ксения Петербуржская.","choices":["Симеона и Анны","Конюшенного ведомства","Смоленской иконы Божьей Матери","Владимирской иконы Божьей Матери"],"answer":2,"steps":["Предание рассказывает, что Ксения тайно помогала рабочим, поднимая по ночам кирпичи.","Речь о церкви Смоленской иконы Божией Матери на Смоленском кладбище Петербурга."],"figure":{"src":"assets/golden-fleece/2022/lessons/8-11/42.webp","alt":"Голубая церковь среди деревьев","width":191,"height":149}},{"title":"Музей песни","question":"На родине этого поэта в 1985 году был открыт музей песни, написанной на его стихи и ставшей одним из символов Великой Отечественной войны.","choices":["М. В. Исаковский","К. М. Симонов","А. Т. Твардовский","С. П. Гудзенко"],"answer":0,"steps":["В Смоленской области действует музей песни «Катюша».","Слова «Катюши» написал уроженец этих мест Михаил Васильевич Исаковский, а музыку — Матвей Блантер."]},{"title":"Название документальной книги","question":"Название книги этого писателя используется как нарицательное обозначение сталинских лагерей.","choices":["Ф. М. Достоевский","А. И. Солженицын","А. П. Чехов","В. Т. Шаламов"],"answer":1,"steps":["В произведении объединены свидетельства о советской лагерной системе и личный опыт автора.","Книга «Архипелаг ГУЛАГ» принадлежит Александру Исаевичу Солженицыну."]},{"title":"Физик и премия мира","question":"Кто из этих советских физиков стал первым российским лауреатом Нобелевской премии мира за правозащитную деятельность?","choices":["И. В. Курчатов","Ю. Б. Харитон","А. Д. Сахаров","С. И. Вавилов"],"answer":2,"steps":["Учёный выступал за права человека, международное сотрудничество и разоружение.","В 1975 году Нобелевскую премию мира присудили Андрею Дмитриевичу Сахарову."]}]);
